<script setup>import {ref} from 'vue';import {photos,projects} from '../data.js';import SpreadGallery from '../components/SpreadGallery.vue';import PhotoViewer from '../components/PhotoViewer.vue';import {readArray} from '../storage.js';const ids=ref(readArray('casil-favorites'));const active=ref(null);function favorite(p){ids.value=ids.value.includes(p.id)?ids.value.filter(i=>i!==p.id):[...ids.value,p.id];localStorage.setItem('casil-favorites',JSON.stringify(ids.value))}function move(n){let i=photos.findIndex(p=>p.id===active.value.id);active.value=photos[(i+n+photos.length)%photos.length]}</script><template><section class="section"><div class="section-head"><div><span class="eyebrow">Browse the collection</span><h2>Find your frame.</h2></div></div><SpreadGallery :photos="photos" :favorites="ids" @favorite="favorite" @open="active=$event"/><PhotoViewer :photo="active" @close="active=null" @move="move"/><div class="project-strip"><h2>Selected projects</h2><div class="cards"><RouterLink v-for="p in projects.filter(p=>p.visibility==='Public')" :key="p.id" class="card project-card" :to="`/project-details?id=${p.id}`"><span class="eyebrow">{{p.category}}</span><h3>{{p.title}}  -> </h3><p>{{p.description}}</p></RouterLink></div></div><p class="notice">Portfolio images are licensed sample placeholders. Replace them with your own or properly licensed photographs.</p></section></template>
